      expect(sessions.length).toBeGreaterThan(0);

      const eventsPath = path.join(sessionsDir, sessions[0], 'events.jsonl');
      const eventsRaw = await fs.readFile(eventsPath, 'utf-8');
      const events = eventsRaw
        .trim()
        .split('\n')
