    const event = {
      ts: Date.now(),
      seq: -1,
      type: 'session.start',
      session_id: '01KF123456789ABCDEFGHJKMNP',
      data: null,
    };

    const result = SessionEventSchema.safeParse(event);
    expect(result.success).toBe(false);
  });
});

