export async function getBudget(
  specDir: string,
  sessionId: string,
): Promise<TaskBudget | null> {
  const budgetPath = getSessionBudgetPath(specDir, sessionId);
  let content: string;
  try {
    content = await fsPromises.readFile(budgetPath, "utf-8");
