    },
    {
      "id": "ac-2",
      "given": "user runs kspec triage list\n",
      "when": "triage records exist\n",
      "then": "displays records with ULID prefix, item snapshot (truncated),\nstatus, action, decided_by, and relative time\n"
    },
    {
      "id": "ac-3",
      "given": "user runs kspec triage list --status pending\n",
      "when": "records with various statuses exist\n",
      "then": "only records matching the status filter are shown\n"
    },
    {
      "id": "ac-4",
      "given": "user runs kspec triage act <triage-ref>\n",
      "when": "the record has status triaged and action promote\n",
      "then": "executes the promote action (creates task from snapshot),\ntransitions record to acted_on with acted_at and result_ref\n"
    },
    {
      "id": "ac-5",
      "given": "user runs kspec triage act <triage-ref> on a record with action delete\n",
      "when": "the referenced inbox item still exists\n",
      "then": "deletes the inbox item without additional confirmation (the\ntriage decision serves as prior authorization) and transitions\nrecord to acted_on\n"
    },
    {
      "id": "ac-6",
      "given": "user runs kspec triage act <triage-ref> on a record with action defer\n",
      "when": "the record is triaged\n",
      "then": "transitions to acted_on with no side effect beyond recording the deferral\n"
    },
    {
      "id": "ac-7",
      "given": "user runs kspec triage act <triage-ref> on a record with action spec-gap\n",
      "when": "the record is triaged\n",
      "then": "creates an observation tagged spec-gap with the item snapshot\nand reasoning, transitions record to acted_on with result_ref\n"
    },
    {
      "id": "ac-8",
      "given": "user runs kspec triage act <triage-ref> on a record with action duplicate\n",
      "when": "the record is triaged\n",
      "then": "deletes the inbox item (prior authorization) and transitions\nrecord to acted_on\n"
    },
    {
      "id": "ac-9",
      "given": "user runs kspec triage start\n",
      "when": "untriaged inbox items exist\n",
      "then": "enters interactive mode presenting items one at a time,\nprompting for action and reasoning, creating triage records\nfor each, skipping already-triaged items\n"
    },
    {
      "id": "ac-10",
      "given": "the user aborts interactive triage mode with Ctrl+C\n",
      "when": "some items have been triaged\n",
      "then": "all previously committed triage records are preserved\n"
    },
    {
      "id": "ac-11",
      "given": "user runs kspec triage record <ref> with --json flag\n",
      "when": "the command succeeds\n",
      "then": "outputs the created triage record as structured JSON\n"
    },
    {
      "id": "ac-12",
      "given": "user runs kspec triage override <triage-ref> --action defer --reasoning \"not ready yet\"\n",
      "when": "the triage record exists with an existing decision\n",
      "then": "updates the record with override_reasoning, override_by,\noverride_at, and the new action\n"
    },
    {
      "id": "ac-13",
      "given": "user runs kspec triage export --format context\n",
      "when": "triage records exist\n",
      "then": "outputs a markdown context block per record with item text,\naction, reasoning, decided_by, evidence refs, and outcome\n"
    },
    {
      "id": "ac-14",
      "given": "user runs kspec triage export --format json\n",
      "when": "triage records exist\n",
      "then": "outputs a JSON array with full TriageRecord objects\n"
    },
    {
      "id": "ac-15",
      "given": "user runs kspec triage act <triage-ref>\n",
      "when": "the record has status acted_on (already executed)\n",
      "then": "returns an error with guidance that the record has already been acted on\n"
    },
    {
      "id": "ac-16",
      "given": "user runs kspec triage act <triage-ref>\n",
      "when": "the record has status pending (no decision yet)\n",
      "then": "returns an error with guidance to record a decision first\n"
    },
    {
      "id": "ac-17",
      "given": "user runs kspec triage act <triage-ref> with --dry-run flag\n",
      "when": "the record has status triaged\n",
      "then": "shows what action would be taken without executing it\n"
