    const triageRecord = kspecJson<{
      _ulid: string;
      item_snapshot: string;
      status: string;
    }>(`triage get @${record._ulid.slice(0, 8)}`, tempDir);
    expect(triageRecord.item_snapshot).toBe("Ephemeral item");
    expect(triageRecord.status).toBe("acted_on");
  });
});

